  testWidgets('Unit 6 Exercise: Pet Screen bark counter, state persistence, and Reset Dialog',
      (WidgetTester tester) async {
    tester.view.physicalSize = const Size(1080, 2400);
    tester.view.devicePixelRatio = 2.0;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    await tester.pumpWidget(const CadanginExerciseApp());
    await tester.pumpAndSettle();

    // Switch to Pet tab
    await tester.tap(find.text('My Pet'));
    await tester.pumpAndSettle();

    expect(find.text('Play Puppy Sound'), findsOneWidget);
    expect(find.text('Whitey has barked 0 times.'), findsOneWidget);

    // Reset button disabled when count is 0
    final Finder resetButton = find.widgetWithText(OutlinedButton, 'Reset count');
    expect(resetButton, findsOneWidget);
    expect(tester.widget<OutlinedButton>(resetButton).onPressed, isNull);

    // Tap play sound to increment bark count
    await tester.tap(find.text('Play Puppy Sound'));
    await tester.pump();
    expect(find.text('Whitey has barked 1 time.'), findsOneWidget);
    expect(tester.widget<OutlinedButton>(resetButton).onPressed, isNotNull);

    // Part A: Switch to Profile and back, count must persist (IndexedStack)
    await tester.tap(find.text('Profile'));
    await tester.pumpAndSettle();
    expect(find.text('My Hobbies'), findsOneWidget);

    await tester.tap(find.text('My Pet'));
    await tester.pumpAndSettle();
    expect(find.text('Whitey has barked 1 time.'), findsOneWidget);

    // Part D: Reset button tap opens AlertDialog
    await tester.tap(resetButton);
    await tester.pumpAndSettle();

    expect(find.byType(AlertDialog), findsOneWidget);
    expect(find.text('Reset Bark Count'), findsOneWidget);
    expect(find.text('Cancel'), findsOneWidget);
    expect(find.text('Reset'), findsOneWidget);

    // Cancel does not reset
    await tester.tap(find.text('Cancel'));
    await tester.pumpAndSettle();
    expect(find.text('Whitey has barked 1 time.'), findsOneWidget);

    // Reset confirms and resets to 0
    await tester.tap(resetButton);
    await tester.pumpAndSettle();
    await tester.tap(find.text('Reset'));
    await tester.pumpAndSettle();
    expect(find.text('Whitey has barked 0 times.'), findsOneWidget);
    expect(tester.widget<OutlinedButton>(resetButton).onPressed, isNull);
  });

