    final Finder firstTile = find.byType(ClipRRect).first;
    await tester.tap(firstTile);
    await tester.pumpAndSettle();

    // On PhotoScreen
    expect(find.widgetWithText(FilledButton, 'Make favorite'), findsOneWidget);

    // Tap Make favorite
    await tester.tap(find.widgetWithText(FilledButton, 'Make favorite'));
    await tester.pumpAndSettle();

    // Back on Gallery grid: star icon is shown on the favorite tile
    expect(find.text('My Gallery'), findsOneWidget);
